diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 09:45:15.235966554 +0000
+++ b/csv.test.ts	2026-10-29 09:46:45.701088489 +0000
@@ -23,3 +23,126 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+/** Feeds `chunks` to a new stream and returns all its rows, or the error one of its calls threw. */
+function stream(chunks: string[]): string[][] | Error {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  try {
+    for (const chunk of chunks) rows.push(...s.push(chunk));
+    rows.push(...s.end());
+    return rows;
+  } catch (e) {
+    return e as Error;
+  }
+}
+
+function parsed(text: string): string[][] | Error {
+  try {
+    return parseCsv(text);
+  } catch (e) {
+    return e as Error;
+  }
+}
+
+function expectSame(text: string, chunks: string[]) {
+  const want = parsed(text);
+  const got = stream(chunks);
+  if (want instanceof Error) expect(got).toBeInstanceOf(SyntaxError);
+  else expect(got).toEqual(want);
+}
+
+test("a row end split between chunks", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+  expectSame("a\r", ["a", "\r"]);
+  expectSame("a\rb", ["a\r", "b"]);
+  expectSame("a\r\r\nb", ["a\r", "\r", "\nb"]);
+});
+
+test("a doubled quote and a closing quote split between chunks", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"')).toEqual([]);
+  expect(s.push('"b"')).toEqual([]);
+  expect(s.push("\n")).toEqual([['a"b']]);
+  expect(s.end()).toEqual([]);
+  expectSame('"a"', ['"a', '"']);
+  expectSame('"a",b', ['"a"', ",b"]);
+  expectSame('"a"\r\n', ['"a"\r', "\n"]);
+});
+
+test("a closing quote followed by a `\\r` that does not start a row end is a SyntaxError", () => {
+  const s = new CsvStream();
+  s.push('"a"\r');
+  expect(() => s.push("b")).toThrow(SyntaxError);
+  expect(stream(['"a"\r'])).toBeInstanceOf(SyntaxError);
+  expect(stream(['"a"', "\r"])).toBeInstanceOf(SyntaxError);
+});
+
+test("the byte order mark is dropped only at the very start, even after empty chunks", () => {
+  expect(stream(["", "", "﻿a"])).toEqual([["a"]]);
+  expect(stream(["﻿", "a"])).toEqual([["a"]]);
+  expect(stream(["﻿"])).toEqual([]);
+  expect(stream(["a", "﻿b"])).toEqual([["a﻿b"]]);
+  expect(stream(["﻿", "﻿"])).toEqual([["﻿"]]);
+  expect(stream(["﻿", '"a"'])).toEqual([["a"]]);
+});
+
+test("the end of the input ends the last row, after a row end or a `,` too", () => {
+  expect(stream([])).toEqual([]);
+  expect(stream(["", ""])).toEqual([]);
+  expect(stream(["a\n"])).toEqual([["a"]]);
+  expect(stream(["a", "\n", ""])).toEqual([["a"]]);
+  expect(stream(["\n"])).toEqual([[""]]);
+  expect(stream(["a,"])).toEqual([["a", ""]]);
+  expect(stream(["a", ","])).toEqual([["a", ""]]);
+  expect(stream(['""'])).toEqual([[""]]);
+});
+
+test("inputs parseCsv rejects make push or end throw a SyntaxError", () => {
+  for (const chunks of [['"a'], ['"a', ""], ['"a""'], ["a", '"'], ['a"b'], ['"a"', "b"], ['"a"', '"', "x"]]) {
+    expect(parsed(chunks.join(""))).toBeInstanceOf(SyntaxError);
+    expect(stream(chunks)).toBeInstanceOf(SyntaxError);
+  }
+  const s = new CsvStream();
+  expect(() => s.push('"a"x')).toThrow(SyntaxError);
+  expect(() => s.push("\n")).toThrow(SyntaxError);
+  const t = new CsvStream();
+  t.push('"a');
+  expect(() => t.end()).toThrow(SyntaxError);
+});
+
+test("calls after end throw", () => {
+  const s = new CsvStream();
+  s.end();
+  expect(() => s.push("a")).toThrow();
+  expect(() => s.end()).toThrow();
+});
+
+test("any input split any way gives the rows parseCsv gives", () => {
+  let seed = 1;
+  const random = (n: number) => {
+    seed = (seed * 1103515245 + 12345) % 2 ** 31;
+    return seed % n;
+  };
+  const alphabet = ["a", "b", ",", '"', "\r", "\n", "﻿"];
+  for (let k = 0; k < 3000; k++) {
+    const text = Array.from({ length: random(12) }, () => alphabet[random(alphabet.length)]).join("");
+    // Every split into chunks of one character, as a whole, and with empty chunks among them.
+    expectSame(text, [...text]);
+    expectSame(text, [text]);
+    expectSame(text, ["", ...[...text].flatMap(c => [c, ""])]);
+    // Every split into two chunks.
+    for (let at = 0; at <= text.length; at++) expectSame(text, [text.slice(0, at), text.slice(at)]);
+    // A random split.
+    const chunks: string[] = [];
+    for (let at = 0; at < text.length; ) {
+      const len = random(4);
+      chunks.push(text.slice(at, at + len));
+      at += len;
+    }
+    expectSame(text, chunks);
+  }
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 09:45:15.236002068 +0000
+++ b/csv.ts	2026-10-29 09:46:23.041087142 +0000
@@ -50,3 +50,163 @@
   rows.push(row);
   return rows;
 }
+
+/** Where a {@link CsvStream} is in the input it has seen so far. */
+type State =
+  | "fieldStart" // at the start of a field: a row's first, or one after a `,`
+  | "unquoted" // in a field that is not quoted
+  | "unquotedCr" // in a field that is not quoted, just after a `\r` that may or may not start a row end
+  | "quoted" // in a quoted field
+  | "quoteInQuoted" // just after a `"` in a quoted field, which either closes it or starts a `""`
+  | "afterClose" // just after a quoted field's closing quote
+  | "afterCloseCr"; // just after a quoted field's closing quote and a `\r`, which must start a row end
+
+/**
+ * {@link parseCsv} for input that arrives in chunks split anywhere. `push` returns the rows whose row end is in
+ * what has arrived so far, and `end` returns the rest once the input is over; together they return the rows
+ * `parseCsv` would return for the whole input, and a `push` or `end` throws a SyntaxError where `parseCsv` would
+ * throw one. Each call's work grows with its chunk and the rows it returns, not with the input before it.
+ */
+export class CsvStream {
+  #state: State = "fieldStart";
+  #field = "";
+  #row: string[] = [];
+  /** The length of the input before the current chunk, for offsets in errors. */
+  #offset = 0;
+  #started = false;
+  #ended = false;
+  #error: SyntaxError | undefined;
+
+  push(chunk: string): string[][] {
+    this.#check();
+    try {
+      return this.#feed(chunk);
+    } catch (e) {
+      if (e instanceof SyntaxError) this.#error = e;
+      throw e;
+    }
+  }
+
+  end(): string[][] {
+    this.#check();
+    this.#ended = true;
+    const rows: string[][] = [];
+    switch (this.#state) {
+      case "fieldStart":
+        // After a `,` the row has a last, empty field; at a row's start there is no row.
+        if (this.#row.length > 0) this.#endRow(rows);
+        break;
+      case "unquotedCr":
+        this.#field += "\r";
+        this.#endRow(rows);
+        break;
+      case "unquoted":
+      case "quoteInQuoted":
+      case "afterClose":
+        this.#endRow(rows);
+        break;
+      case "quoted":
+        throw (this.#error = new SyntaxError("a quoted field is still open at the end of the input"));
+      case "afterCloseCr":
+        throw (this.#error = new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.#offset - 1}`));
+    }
+    return rows;
+  }
+
+  #check() {
+    if (this.#error) throw this.#error;
+    if (this.#ended) throw new Error("the stream has already ended");
+  }
+
+  #feed(chunk: string): string[][] {
+    const rows: string[][] = [];
+    const n = chunk.length;
+    let i = 0;
+    if (!this.#started && n > 0) {
+      this.#started = true;
+      if (chunk[0] === "﻿") i = 1;
+    }
+    while (i < n) {
+      switch (this.#state) {
+        case "fieldStart":
+          if (chunk[i] === '"') {
+            i++;
+            this.#state = "quoted";
+          } else this.#state = "unquoted";
+          break;
+        case "unquoted": {
+          let j = i;
+          while (j < n) {
+            const c = chunk[j];
+            if (c === "," || c === "\n" || c === "\r" || c === '"') break;
+            j++;
+          }
+          this.#field += chunk.slice(i, j);
+          i = j;
+          if (i === n) break;
+          const c = chunk[i++];
+          if (c === ",") this.#endField();
+          else if (c === "\n") this.#endRow(rows);
+          else if (c === "\r") this.#state = "unquotedCr";
+          else throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.#offset + i - 1}`);
+          break;
+        }
+        case "unquotedCr":
+          if (chunk[i] === "\n") {
+            i++;
+            this.#endRow(rows);
+          } else {
+            this.#field += "\r";
+            this.#state = "unquoted";
+          }
+          break;
+        case "quoted": {
+          const j = chunk.indexOf('"', i);
+          if (j < 0) {
+            this.#field += chunk.slice(i);
+            i = n;
+          } else {
+            this.#field += chunk.slice(i, j);
+            i = j + 1;
+            this.#state = "quoteInQuoted";
+          }
+          break;
+        }
+        case "quoteInQuoted":
+          if (chunk[i] === '"') {
+            i++;
+            this.#field += '"';
+            this.#state = "quoted";
+          } else this.#state = "afterClose";
+          break;
+        case "afterClose": {
+          const c = chunk[i++];
+          if (c === ",") this.#endField();
+          else if (c === "\n") this.#endRow(rows);
+          else if (c === "\r") this.#state = "afterCloseCr";
+          else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.#offset + i - 1}`);
+          break;
+        }
+        case "afterCloseCr":
+          if (chunk[i] !== "\n") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.#offset + i - 1}`);
+          i++;
+          this.#endRow(rows);
+          break;
+      }
+    }
+    this.#offset += n;
+    return rows;
+  }
+
+  #endField() {
+    this.#row.push(this.#field);
+    this.#field = "";
+    this.#state = "fieldStart";
+  }
+
+  #endRow(rows: string[][]) {
+    this.#endField();
+    rows.push(this.#row);
+    this.#row = [];
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 09:45:15.242513799 +0000
+++ b/csv.test.ts	2026-10-29 09:47:01.680950143 +0000
@@ -23,3 +23,142 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function streamAll(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows = chunks.flatMap((c) => s.push(c));
+  return [...rows, ...s.end()];
+}
+
+// Every way of splitting `text` into two or three chunks, empty chunks included.
+function splits(text: string): string[][] {
+  const out: string[][] = [];
+  for (let a = 0; a <= text.length; a++) {
+    for (let b = a; b <= text.length; b++) out.push([text.slice(0, a), text.slice(a, b), text.slice(b)]);
+  }
+  return out;
+}
+
+function expectSameAsParseCsv(chunks: string[]) {
+  const text = chunks.join("");
+  let expected: string[][] | SyntaxError;
+  try {
+    expected = parseCsv(text);
+  } catch (e) {
+    expected = e as SyntaxError;
+  }
+  if (expected instanceof SyntaxError) {
+    expect(() => streamAll(chunks)).toThrow(expected.message);
+    expect(() => streamAll(chunks)).toThrow(SyntaxError);
+  } else {
+    expect(streamAll(chunks)).toEqual(expected);
+  }
+}
+
+test("a stream matches parseCsv when a chunk ends inside a row end, a doubled quote or after a closing quote", () => {
+  for (const text of [
+    "a\r\nb",
+    "a\rb\r\n",
+    "a\r",
+    "a\r\r\n\r",
+    '"a""b"\r\n"c"',
+    '"a"\r\n',
+    '"a",""\n""',
+    '"x\r\ny"\r\n',
+    "a,\n,",
+    "\n\n",
+  ]) {
+    for (const chunks of splits(text)) expectSameAsParseCsv(chunks);
+  }
+});
+
+test("a stream rejects what parseCsv rejects, wherever the chunks are split", () => {
+  for (const text of ['"a"b', '"a"\rb', '"a"\r', '"a', '"a""', 'a"b', 'a\r"', "a\n\"b\"c"]) {
+    for (const chunks of splits(text)) expectSameAsParseCsv(chunks);
+  }
+});
+
+test("a stream drops a byte order mark only at the very start, even after empty chunks", () => {
+  expect(streamAll(["", "﻿a"])).toEqual([["a"]]);
+  expect(streamAll(["﻿", "﻿a"])).toEqual([["﻿a"]]);
+  expect(streamAll(["a", "﻿"])).toEqual([["a﻿"]]);
+  expect(streamAll(["﻿"])).toEqual([]);
+  expect(streamAll([])).toEqual([]);
+  expect(streamAll(["", ""])).toEqual([]);
+});
+
+test("a stream returns a row as soon as the \\n of its \\r\\n arrives, and not before", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.push("\rc\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["b\rc"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a stream keeps failing after a SyntaxError and refuses input after the end", () => {
+  const s = new CsvStream();
+  expect(() => s.push('"a"x')).toThrow(SyntaxError);
+  expect(() => s.push("b")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+  const t = new CsvStream();
+  t.end();
+  expect(() => t.push("a")).toThrow();
+});
+
+test("a stream matches parseCsv on random inputs split at random, and returns rows as soon as they end", () => {
+  let seed = 12345;
+  const random = (n: number) => {
+    seed = (seed * 1103515245 + 12345) % 2147483648;
+    return seed % n;
+  };
+  const alphabet = ["a", "b", ",", '"', '""', "\r", "\n", "\r\n", "﻿"];
+  for (let run = 0; run < 3000; run++) {
+    let text = "";
+    for (let n = random(16); n > 0; n--) text += alphabet[random(alphabet.length)];
+    const chunks: string[] = [];
+    for (let at = 0; at < text.length; ) {
+      const size = random(5);
+      chunks.push(text.slice(at, at + size));
+      at += size;
+    }
+    expectSameAsParseCsv(chunks);
+
+    // After each chunk, the rows so far are the rows of the input so far whose row end has arrived.
+    const s = new CsvStream();
+    const rows: string[][] = [];
+    let sofar = "";
+    try {
+      for (const chunk of chunks) {
+        rows.push(...s.push(chunk));
+        sofar += chunk;
+        let done: string[][];
+        try {
+          done = parseCsv(sofar);
+        } catch {
+          continue;
+        }
+        expect(rows).toEqual(sofar.endsWith("\n") ? done : done.slice(0, -1));
+      }
+    } catch (e) {
+      expect(e).toBeInstanceOf(SyntaxError);
+    }
+  }
+});
+
+test("a stream's work for a chunk does not grow with the input before it", () => {
+  const n = 1_000_000;
+  const started = performance.now();
+  for (const [first, last] of [["", ""], ['"', '"']]) {
+    const s = new CsvStream();
+    s.push(first);
+    for (let i = 0; i < n; i++) expect(s.push(i % 2 ? "\r" : "x").length).toBe(0);
+    s.push(last);
+    expect(s.end()[0]![0]!.length).toBe(n);
+  }
+  const s = new CsvStream();
+  let count = 0;
+  for (let i = 0; i < n; i++) count += s.push(i % 2 ? "\n" : "x,").length;
+  expect(count).toBe(n / 2);
+  expect(performance.now() - started).toBeLessThan(10_000);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 09:45:15.242548002 +0000
+++ b/csv.ts	2026-10-29 09:46:20.993087020 +0000
@@ -50,3 +50,187 @@
   rows.push(row);
   return rows;
 }
+
+type StreamState =
+  | "fieldStart" // nothing of the current field has been read
+  | "unquoted" // inside a field that is not quoted
+  | "unquotedCr" // inside a field that is not quoted, just after a `\r` that may start a row end
+  | "quoted" // inside a quoted field
+  | "quotedQuote" // inside a quoted field, just after a `"` that either closes it or starts a `""`
+  | "closed" // just after the closing quote of a field
+  | "closedCr" // just after a `\r` that follows a closing quote, so it must be followed by `\n`
+  | "failed"
+  | "ended";
+
+const unquotedSpecial = /[,\r\n"]/g;
+
+/**
+ * Reads CSV, as `parseCsv` describes it, from an input that arrives in chunks of any size. The rows from all the
+ * calls together equal `parseCsv` of the whole input, and an input `parseCsv` rejects makes a call throw the same
+ * SyntaxError. Each chunk is read once, so a chunk costs the same however much input came before it.
+ */
+export class CsvStream {
+  private state: StreamState = "fieldStart";
+  private offset = 0; // offset in the whole input of the start of the current chunk
+  private started = false; // whether any of the input has been read, so a `﻿` is no longer at its very start
+  private row: string[] = [];
+  private field = "";
+  private error: SyntaxError | undefined;
+
+  /** Reads the next chunk of the input and returns the rows whose row end is in it. */
+  push(chunk: string): string[][] {
+    this.check();
+    const rows: string[][] = [];
+    try {
+      this.read(chunk, rows);
+    } catch (e) {
+      if (e instanceof SyntaxError) {
+        this.state = "failed";
+        this.error = e;
+      }
+      throw e;
+    }
+    return rows;
+  }
+
+  /** Ends the input and returns the rows that are still open. */
+  end(): string[][] {
+    this.check();
+    const at = this.offset;
+    const fail = (message: string) => {
+      this.state = "failed";
+      this.error = new SyntaxError(message);
+      throw this.error;
+    };
+    switch (this.state) {
+      case "fieldStart":
+        if (this.row.length === 0) break; // the input is empty or ends just after a row end
+        this.endField();
+        break;
+      case "unquotedCr":
+        this.field += "\r";
+        this.endField();
+        break;
+      case "quoted":
+        fail("a quoted field is still open at the end of the input");
+        break;
+      case "closedCr":
+        fail(`unexpected "\\r" after a closing quote at offset ${at - 1}`);
+        break;
+      default: // "unquoted", "quotedQuote" and "closed"
+        this.endField();
+    }
+    this.state = "ended";
+    const rows = this.row.length > 0 ? [this.row] : [];
+    this.row = [];
+    return rows;
+  }
+
+  private check() {
+    if (this.state === "failed") throw this.error;
+    if (this.state === "ended") throw new Error("the input has already ended");
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+  }
+
+  private endRow(rows: string[][]) {
+    this.endField();
+    rows.push(this.row);
+    this.row = [];
+  }
+
+  private read(text: string, rows: string[][]) {
+    let i = 0;
+    if (!this.started && text.length > 0) {
+      this.started = true;
+      if (text[0] === "﻿") i = 1;
+    }
+    while (i < text.length) {
+      switch (this.state) {
+        case "fieldStart":
+          if (text[i] === '"') {
+            i++;
+            this.state = "quoted";
+          } else {
+            this.state = "unquoted";
+          }
+          break;
+        case "unquoted": {
+          unquotedSpecial.lastIndex = i;
+          const found = unquotedSpecial.exec(text);
+          const stop = found ? found.index : text.length;
+          this.field += text.slice(i, stop);
+          i = stop;
+          if (!found) break;
+          const c = text[i++];
+          if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.offset + i - 1}`);
+          if (c === ",") {
+            this.endField();
+            this.state = "fieldStart";
+          } else if (c === "\n") {
+            this.endRow(rows);
+            this.state = "fieldStart";
+          } else {
+            this.state = "unquotedCr";
+          }
+          break;
+        }
+        case "unquotedCr":
+          if (text[i] === "\n") {
+            i++;
+            this.endRow(rows);
+            this.state = "fieldStart";
+          } else {
+            this.field += "\r";
+            this.state = "unquoted";
+          }
+          break;
+        case "quoted": {
+          const quote = text.indexOf('"', i);
+          const stop = quote < 0 ? text.length : quote;
+          this.field += text.slice(i, stop);
+          i = stop;
+          if (quote >= 0) {
+            i++;
+            this.state = "quotedQuote";
+          }
+          break;
+        }
+        case "quotedQuote":
+          if (text[i] === '"') {
+            i++;
+            this.field += '"';
+            this.state = "quoted";
+          } else {
+            this.state = "closed";
+          }
+          break;
+        case "closed": {
+          const c = text[i++];
+          if (c === ",") {
+            this.endField();
+            this.state = "fieldStart";
+          } else if (c === "\n") {
+            this.endRow(rows);
+            this.state = "fieldStart";
+          } else if (c === "\r") {
+            this.state = "closedCr";
+          } else {
+            throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.offset + i - 1}`);
+          }
+          break;
+        }
+        case "closedCr":
